//! Icon set + display registry for Macro Output ports.
//!
//! ## Icons
//! Every `.svg` in `app/assets/general/` is embedded at compile time. The set
//! is generated by `build.rs` into `ALL_ICONS` (not hardcoded here), so the
//! shippable icons are whatever lives in that folder — drop one in / rename /
//! remove it and the pickers follow on the next build. A port stores an icon
//! KEY (`MacroPortDef::icon`, = the file stem); [`macro_icon_svg`] resolves it
//! back to bytes and [`macro_icon_texture`] rasterizes + caches it for
//! cells/chips. [`ALL_ICONS`] drives the icon picker menu in the node body.
//!
//! ## Display registry
//! Macro pins ("macro:{id}") appear in mapping `out` arrays, mapping-card
//! chips, the KB/M picker, and Touch Zones' analog-output checks — far from
//! the Macro node that defines them, and several of those sites have no
//! `egui::Context` in reach (gamepad-nav helpers). So the app publishes a
//! per-frame snapshot of all defined ports (active tab, including nested
//! sub-patches) into a process-global; [`registry`] reads it back anywhere a
//! pin id needs a name/icon/type. Same single-writer-per-frame global pattern
//! as `flexinput_engine::current_sample_rate`.

use std::sync::Arc;

use flexinput_core::SignalType;

/// One defined macro port, as seen by pickers and chip renderers.
#[derive(Debug, Clone)]
pub struct MacroDisplayEntry {
    /// Bus pin id: `macro:{port_id}`.
    pub pin: String,
    /// User-facing port name.
    pub name: String,
    /// Icon key into [`ALL_ICONS`]; empty = no icon (render the name).
    pub icon: String,
    /// Custom icon SVG text embedded in the patch; non-empty wins over `icon`.
    pub icon_svg: String,
    pub signal_type: SignalType,
}

static REGISTRY: std::sync::RwLock<Option<Arc<Vec<MacroDisplayEntry>>>> =
    std::sync::RwLock::new(None);

/// Publish this frame's macro port table (called once per frame by `app.rs`).
pub fn publish_registry(entries: Arc<Vec<MacroDisplayEntry>>) {
    *REGISTRY.write().unwrap() = Some(entries);
}

/// The current macro port table (empty if nothing published yet this session).
pub fn registry() -> Arc<Vec<MacroDisplayEntry>> {
    REGISTRY.read().unwrap().clone().unwrap_or_default()
}

/// Look up one macro pin id in the registry.
pub fn registry_entry(pin: &str) -> Option<MacroDisplayEntry> {
    registry().iter().find(|e| e.pin == pin).cloned()
}

// ── Embedded SVG bytes (app/assets/general/) ─────────────────────────────────
//
// `ALL_ICONS` + `ICON_CATEGORIES` are generated at build time by `build.rs`
// from every `.svg` under `app/assets/general/` — so the shippable icon set is
// defined by that folder, not by a hardcoded list here. Add / rename / remove
// an SVG (or a whole category sub-folder) and the pickers update on the next
// build with no code change. Each entry is `(key, human label, category, svg
// bytes)`; the `key` is the file stem, persisted in `macro_ports.icon`, so
// renaming a file changes its key and orphans any saved reference. The
// `category` is the prettified immediate sub-folder under `general/` (loose
// files are "Uncategorized") and drives the icon picker's category dropdown.
include!(concat!(env!("OUT_DIR"), "/generated_macro_icons.rs"));

/// Resolve an icon key to its embedded SVG bytes.
pub fn macro_icon_svg(key: &str) -> Option<&'static [u8]> {
    ALL_ICONS.iter().find(|(k, _, _, _)| *k == key).map(|(_, _, _, b)| *b)
}

/// The gamepad `Skin` used to render dynamic `gp:<pin>` icons this frame — the
/// current connected pad's family, published each frame by the app (else Xbox).
pub fn current_gp_skin(ctx: &egui::Context) -> crate::canvas::remapper_icons::Skin {
    ctx.data(|d| d.get_temp::<crate::canvas::remapper_icons::Skin>(
        egui::Id::new("fxi_current_gp_skin")))
        .unwrap_or(crate::canvas::remapper_icons::Skin::Xbox)
}

/// Resolve an icon KEY to SVG bytes, understanding the dynamic `gp:<pin>` scheme
/// (a gamepad-input glyph in `skin`'s style, native fallback) in addition to the
/// build-time icon set. THE single place that knows the `gp:` prefix; used by the
/// texture path and the SVG-decoration rasterize path alike.
pub fn icon_key_svg_bytes(icon_key: &str, skin: crate::canvas::remapper_icons::Skin)
    -> Option<&'static [u8]>
{
    if let Some(pin) = icon_key.strip_prefix("gp:") {
        return crate::canvas::remapper_icons::gp_pin_svg(skin, pin);
    }
    macro_icon_svg(icon_key)
}

/// Rasterize a macro icon to a cached white-on-transparent texture, sized for
/// a cell/chip of `size_pts` logical pixels (mirrors `kbm_cell_texture`).
pub fn macro_icon_texture(
    ctx: &egui::Context,
    key: &str,
    size_pts: f32,
) -> Option<egui::TextureHandle> {
    let bytes = macro_icon_svg(key)?;
    let text = std::str::from_utf8(bytes).ok()?;
    let cache_salt = bytes.as_ptr() as usize as u64;
    svg_texture_cached(ctx, text, cache_salt, size_pts)
}

/// Resolve a PORT's icon to a texture: the embedded-in-patch custom SVG when
/// present, else the embedded icon set by key, else `None` (render the name).
/// This is THE resolver every display site uses (body button, picker cells,
/// mapping-card chips, zone overlays) so custom icons appear everywhere the
/// stock ones do.
pub fn macro_port_icon_texture(
    ctx: &egui::Context,
    icon_key: &str,
    icon_svg: &str,
    size_pts: f32,
) -> Option<egui::TextureHandle> {
    if !icon_svg.is_empty() {
        // Content-hash the SVG so edits/reloads get a fresh texture and
        // identical icons on several ports share one.
        use std::hash::{Hash, Hasher};
        let mut h = std::collections::hash_map::DefaultHasher::new();
        icon_svg.hash(&mut h);
        return svg_texture_cached(ctx, icon_svg, h.finish(), size_pts);
    }
    // Dynamic gamepad-input glyph (`gp:<pin>`): resolve for the CURRENT pad skin.
    // The cache salt is the resolved bytes' pointer, which differs per skin, so a
    // pad change re-rasterizes → every gp icon restyles with no per-site work.
    if icon_key.starts_with("gp:") {
        let bytes = icon_key_svg_bytes(icon_key, current_gp_skin(ctx))?;
        let text = std::str::from_utf8(bytes).ok()?;
        return svg_texture_cached(ctx, text, bytes.as_ptr() as usize as u64, size_pts);
    }
    macro_icon_texture(ctx, icon_key, size_pts)
}

/// Corner badge telling a Virtual Menu's targets apart — Show, Select, Next
/// and Previous all wear the menu's own icon. A dark disc in `icon`'s
/// top-right corner (the bottom-right one is a timed output's duration)
/// carrying an eye, a check, or a right / left arrowhead, drawn in `tint`.
/// No-op for any pin that isn't a menu target.
pub fn paint_menu_target_badge(
    painter: &egui::Painter,
    icon: egui::Rect,
    pin: &str,
    tint: egui::Color32,
) {
    use flexinput_core::menu::{parse_target_pin, TargetPin};
    use egui::{pos2, Pos2, Stroke};
    let Some((_, target)) = parse_target_pin(pin) else { return };
    let r = (icon.width().min(icon.height()) * 0.22).clamp(4.5, 9.0);
    let c = pos2(icon.right() - r, icon.top() + r);
    painter.circle(c, r, egui::Color32::from_black_alpha(225),
        Stroke::new(1.0, egui::Color32::from_gray(150)));
    let g = r * 0.62;
    let at = |x: f32, y: f32| -> Pos2 { pos2(c.x + x * g, c.y + y * g) };
    match target {
        TargetPin::Show => {
            // A lens with a dark pupil.
            const N: usize = 8;
            let mut pts: Vec<Pos2> = Vec::with_capacity(2 * N + 2);
            for i in 0..=N {
                let th = std::f32::consts::PI * i as f32 / N as f32;
                pts.push(at(-th.cos(), -0.62 * th.sin()));
            }
            for i in 1..N {
                let th = std::f32::consts::PI * i as f32 / N as f32;
                pts.push(at(th.cos(), 0.62 * th.sin()));
            }
            painter.add(egui::Shape::convex_polygon(pts, tint, Stroke::NONE));
            painter.circle_filled(c, g * 0.34, egui::Color32::from_black_alpha(235));
        }
        TargetPin::Select => {
            let s = Stroke::new((r * 0.3).max(1.2), tint);
            painter.line_segment([at(-0.7, 0.0), at(-0.2, 0.5)], s);
            painter.line_segment([at(-0.2, 0.5), at(0.7, -0.5)], s);
        }
        TargetPin::Next | TargetPin::Prev => {
            let d = if target == TargetPin::Next { 1.0 } else { -1.0 };
            painter.add(egui::Shape::convex_polygon(
                vec![at(-0.5 * d, -0.7), at(0.7 * d, 0.0), at(-0.5 * d, 0.7)],
                tint,
                Stroke::NONE,
            ));
        }
    }
}

/// Rasterize + cache one SVG at `size_pts`, keyed by (`cache_salt`, size).
fn svg_texture_cached(
    ctx: &egui::Context,
    svg_text: &str,
    cache_salt: u64,
    size_pts: f32,
) -> Option<egui::TextureHandle> {
    let size_px = (size_pts * ctx.pixels_per_point()).round() as u32;
    let cache_key = egui::Id::new(("macro_icon", cache_salt, size_px));
    if let Some(tex) = crate::widgets::tex_cache::get(&ctx, cache_key) {
        return Some(tex);
    }
    let img = crate::canvas::viewer::rasterize_svg_recolored(
        svg_text, size_px, size_px, "override", egui::Color32::TRANSPARENT)?;
    let handle = ctx.load_texture(
        format!("macro_icon_{cache_salt:x}_{size_px}"), img, egui::TextureOptions::LINEAR);
    crate::widgets::tex_cache::put(&ctx, cache_key, handle.clone());
    Some(handle)
}
